	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		_, _ = w.Write([]byte(`{"results":[{"name":"nginx","description":"`))
		chunk := []byte(strings.Repeat("a", 64<<10))
		for i := 0; i < 400; i++ { // up to 25 MiB offered
			n, err := w.Write(chunk)
			written.Add(int64(n))
			if err != nil {
				return
			}
		}
